["A group leader may select this option to add the entire group to the battleground queue. Your group will enter the battleground at the same time."]="Um líder de grupo pode selecionar essa opção para adicionar o grupo todo a uma fila de campo de batalha. O grupo entrará no campo de batalha ao mesmo tempo.",
["A guy walked up to me and said, \"I'm a teepee, I'm a wigwam, I'm a teepee, I'm a wigwam.\"  I said, \"Relax, man, you're too tense.\""]="Um cara chegou e disse: \"Sou uma tenda, sou uma cabana, sou uma tenda, sou uma cabana.\" Eu respondi: \"Relaxa, cara, você está muito tenso.\"",
