["Add or remove the selected quest from your quest watch list. You can click on a quest in your quest watch list to see the details of that quest."]="Adicione ou remova a missão selecionada da lista de missões acompanhadas. É possível clicar em uma missão na lista de missões acompanhadas para visualizar os detalhes.",
