["Additionally, we encourage all players to first utilize the forums and the website to pursue information about their respective issues at |cffffd200www.worldofwarcraft.com|r , and request that specific attention be paid to our game policies at |cffffd200www.worldofwarcraft.com/policy/|r ."]="Recomendamos que todos os jogadores consultem primeiro o fórum e o site para buscar informações sobre seus problemas e leiam atentamente as políticas do jogo em |cffffd200www.worldofwarcraft.com/policy/|r.",
["Adds a new player to the guild."]="Adiciona um novo jogador à guilda.",
["Adds a new player to the team."]="Adiciona um novo jogador à equipe.",
["Adds a player to your friends list. You will be notified whenever a friend logs on or off. Other players do not know whether they are on your friends list."]="Adiciona um jogador à lista de amigos. Você será notificado sempre que um jogador conectar ou desconectar. Os outros jogadores não sabem se estão na sua lista de amigos.",
["Adds a player to your ignore list. You will no longer see messages or other text from players on your ignore list, nor will these players be able to communicate with you in any other way."]="Adiciona um jogador à lista de ignorados. Você não verá mais mensagens ou texto de jogadores que estejam na lista de ignorados. Eles também não serão capazes de se comunicar com você de nenhuma forma.",
["Adds a player to your mute list. You will no longer hear voice chat from players on your mute list."]="Adiciona um jogador à lista de silenciados. Você não ouvirá mais a voz dos jogadores na sua lista de silenciados.",
["Adds to your Attack Power, Damage-Per-Second. Strength\ndoes not affect Critical Hit chances at all. Strength does\nnot improve your chance to block, but rather the amount\nblocked when you succeed. This amount is determined in\npart by Strength (and the other part by your shield). "]="Aumenta o poder de ataque e o dano por segundo. Força\nnão afeta a chance de acerto crítico em hipótese alguma.\nForça não aumenta a sua chance de bloqueio, mas sim a quantidade\nde dano bloqueada. Esse valor é determinado em parte\npela Força e em parte pelo seu escudo.",
