["Allows you to view information about your guild, and players in it. If you are an officer, you can also manage your guild from this tab."]="Exibe informações sobre a guilda e os jogadores que fazem parte dela. Caso seja um oficial, você também pode gerenciar a guilda a partir desta aba.",
