["Each of the 21 gray bars below should be distinct from one another. Adjust the gamma slider until you can distinguish between each shade of gray. If using the slider alone is not enough to achieve this, adjust your monitor's brightness and contrast settings until satisfied."]="As 21 barras de cor cinza abaixo devem ser distintas umas das outras. Ajuste o nível de gama até que seja possível distinguir todos os tons de cinza. Se isso não for possível apenas com o controle deslizante, ajuste as configurações de brilho e de contraste do monitor.",
["Each time you assist in killing a civilian in PvP that is too low of a level to give you experience (a gray level number), you will get a dishonorable kill.   Each dishonorable kill you get immediately reduces your overall ranking slightly, and each additional dishonorable kill you get during a single day has a larger effect than the last one.   Dishonorable kills are directly applied to your ranking."]="Cada vez que ajudar a matar um civil em JxJ que seja de nível muito baixo para conceder experiência (número do nível em cinza), você receberá um abate desonroso.   Cada abate desonroso reduz imediatamente a posição geral aos poucos e cada abate desonroso adicional no mesmo dia tem efeito maior que o anterior.   Os abates desonrosos têm influência direta na posição.",
["Each time you or a group you are part of does damage to an enemy player in PvP that is subsequently killed you gain an honorable kill.   You only get an honorable kill if the target’s difficulty is green or better (the target would give you experience if it were a monster).    Only enemy players give honorable kills."]="Cada vez que você ou seu grupo causar dano a um jogador adversário em JxJ e este for morto em seguida, você obterá um abate honroso.   Só é possível obter abates honrosos se a dificuldade do alvo for verde ou acima (o alvo daria experiência se fosse um monstro).    Somente jogadores adversários podem proporcionar mortes honrosas.",
["Each victory subsequent to the first each day will earn you:"]="Cada vitória subsequente à primeira concederá a você:",
