["Enable mature language filtering.\n\n|cffff0000Warning:|r Battle.net is unavailable, so this setting may not be saved."]="Ativa filtro de linguagem inadequada.\n\n|cffff0000Aviso:|r O Battle.net não está disponível. A configuração não foi salva.",
["Enable the playing of alert sounds when aggro advances to a higher level."]="Ativa a reprodução de sons de alerta quando o nível de agro aumentar.",
["Enable this option for a more responsive cursor unless you have cursor problems."]="Ative esta opção para aumentar a sensibilidade do cursor, a menos que tenha problemas com o cursor.",
["Enable this option for smooth lighting across characters."]="Ative essa opção para suavizar as luzes dos personagens.",
["Enable this option if you have a World of Warcraft Gaming Mouse and you wish to bind keys to the extra buttons."]="Ative esta opção se tiver um Gaming Mouse do World of Warcraft e desejar vincular teclas aos botões extras.",
