["Enable this to prevent resizing the game window."]="Ative esta opção para bloquear o redimensionamento da janela do jogo.",
["Enable to allow sounds to play even when World of Warcraft is in the background."]="Ative essa opção para ouvir os sons mesmo quando o World of Warcraft estiver em segundo plano.",
["Enable to continuously play background music."]="Ative esta opção para ouvir a música de fundo ininterruptamente.",
["Enables a full screen effect that softens edges and lighting. Disabling this can sometimes improve performance."]="Ativa um efeito de tela cheia que suaviza as bordas e a iluminação. Desativar esta opção poderá melhorar o desempenho.",
["Enables all pixel shaders."]="Ativa o sombreado de todos os pixels.",
["Enables character shadows for all characters within the game.  Disabling this can sometimes improve performance."]="Ativa a exibição de sombras para todos os personagens do jogo.  Desativar esta opção poderá melhorar o desempenho.",
["Enables high quality filtering of texture maps. Turn this feature off to increase performance."]="Ativa filtro de alta qualidade de mapeamento de texturas. Desative esta opção para melhorar o desempenho.",
["Enables or disables all sound."]="Ativa ou desativa todos os sons.",
["Enables or disables game sound effects."]="Ativa ou desativa os efeitos sonoros do jogo.",
["Enables reverb sound effects.  This will affect performance."]="Ativa efeitos sonoros e reverberação. Isso afetará o desempenho.",
["Enables software emulation for headphone surround sound."]="Ativa a emulação de software para o som surround de fones de ouvido.",
["Enables specular highlights on terrain. Disabling this can sometimes improve performance."]="Ativa realces especulares no terreno. Desativar esta opção poderá melhorar o desempenho.",
["Enables speech from errors (e.g. \"Target out of range\")."]="Ativa a mensagem sonora de erros (ex. \"Alvo fora de alcance\").",
["Enables speech from groupmates."]="Ativa o diálogo entre membros de grupos.",
["Enables stereoscopic (3D) video."]="Ativa vídeo estereoscópico (3D).",
["Enables subtitles during the intro cinematic."]="Ativa os subtítulos durante o vídeo introdutório.",
["Enables the projecting of textures to the environment. Disabling this may greatly improve performance."]="Ativa a projeção de texturas no ambiente. Desativar esta opção poderá melhorar bastante o desempenho.",
["Enables the use of hardware for 3D sound management. This may alter your sound performance."]="Permite o uso de hardware de gerenciamento de som 3D. Isso poderá alterar o desempenho do som.",
["Enables the use of vertex shaders to speed animation. Enable this to maximize performance."]="Permite o uso de sombreados de vértices para acelerar as animações. Ative essa opção para maximizar o desempenho.",
["Enables triple buffering of frames when vertical sync is enabled. Selecting triple buffering may even out frame rate spikes, but may also cause slight input lag."]="Ativa buffer triplo para os quadros quando o sincronização vertical estiver ativado. Selecionar buffer triplo poderá amenizar as variações de taxa de quadros, mas também poderá causar atraso na entrada de comandos.",
["Enables your microphone."]="Ativa o microfone.",
["Enabling Simple Chat will cause your chat window settings to be lost. Are you sure you want to enable Simple Chat?"]="Ativar Bate-papo Simples fará com que as configurações da janela de bate-papo sejam perdidas. Tem certeza de que deseja ativar Bate-papo Simples?",
