["For assistance with any issues like these, please contact Billing & Account Services:|n|nBy Phone at:  |cffffd200(800) 59-BLIZZARD|r|nBy Web at:  |cffffd200http://us.blizzard.com/support/index.xml?gameId=11|r|nBy Email at:  |cffffd200billing@blizzard.com|r |n|nWe also recommend you check the Account Management page at: |n|n|cffffd200www.worldofwarcraft.com/account|r |n|nOn the Account Management page, you can view your subscription information, add game cards, and access other important account functions and options."]="Para obter ajuda com problemas como esse, entre em contato com o Atendimento de Cobrança e Conta:|n|nTelefone: |cffffd200(800) 59-BLIZZARD|r|nWeb: |cffffd200http://us.blizzard.com/support/index.xml?gameId=11|r|nE-mail: |cffffd200billing@blizzard.com|r |n|nRecomendamos que verifique a página Gerenciamento de Conta: |n|n|cffffd200www.worldofwarcraft.com/account|r |n|nNa página Gerenciamento de Conta, é possível visualizar informações sobre a sua assinatura, adicionar cartões de jogo e acessar outras funções e opções importantes da conta.",
["For assistance with in-game support, please use the following options to submit a petition for GM assistance or report an issue."]="Para obter auxílio com suporte ao jogo, use as opções abaixo para enviar uma petição a um MJ ou reportar um problema.",
