["Game Masters are normally available to assist 24 hours a day. The next available Game Master will be able to assist you no matter which character you are currently playing on.  Please keep in mind wait times may vary, and there are some issues that Game Masters will |cffffd200NOT|r be able to assist you with.  Those issues include, but are |cffffd200NOT|r limited to the following:"]="Normalmente, os mestres de jogo estão disponíveis para ajudar você 24 horas ao dia. O mestre de jogo que estiver disponível ajudará você independentemente de o personagem com o que estiver jogando. Tenha em mente que os tempos de espera podem variar e que existem alguns temas com os que os mestres de jogo |cffffd200NÃO|r poderão ajudar você, incluindo mas |cffffd200NÃO|r limitando-se a:",
