["Honor Gained Today"]="Honra ganha hoje",
["Honor Points"]="Pontos de Honra",
["Honor is gained by killing members of the opposite faction in PvP combat. You can use honor points to purchase special items."]="Ganha-se honra ao matar membros da facção oposta em combate JxJ. É possível usar os pontos de honra para comprar itens especiais.",
["Honor is what you gain by making honorable kills in PvP combat.   How much honor you gain per kill is determined by how much damage you (or your group) did to the player that was killed, with more damage done equaling more honor.   This honor gain is split amongst the members of your group or raid group.   Also you will gain less honor for killing the same player over and over again in a short period of time, so after a few kills of the same player you will get little or no honor from killing them."]="Você ganha honra por realizar abates honrosos em combates JxJ.   A quantidade de honra obtida por abate é determinada pelo dano que você (ou seu grupo) causou ao jogador que foi abatido. Um dano maior concede mais honra.   A honra obtida é dividida entre os integrantes do grupo ou grupo do raide.   A honra obtida será menor se abater o mesmo jogador várias vezes em um curto período de tempo. Após abater o mesmo jogador algumas vezes, você receberá pouca ou nenhuma honra do abate.",
["Honor required it."]="A honra exigia isso.",
["Honorable\nKills"]="Jogadores Abatidos\nHonrosamente",
["Honorable Kills"]="Jogadores abatidos honrosamente",
