["Horde zone message"]="Mensagem de zona da Horda",
["Horn Color"]="Cor do chifre",
["Horn Style"]="Estilo de chifre",
["Hostile"]="Hostil",
["Hot Issue"]="Assunto importante",
["How are you?"]="Como você está?",
["How does a Tauren hide in a cherry tree?  He paints his hooves red."]="Como se esconde um tauren em um cerejeira? Se pinta as cascos de vermelho.",
["How generous."]="Que generosidade.",
["How kind of you."]="Que gentil é.",
["How much memory your AddOns are using. You can get to the addon management page from the character select screen."]="O quanto de memória seus AddOns estão usando. Você pode acessar a página de controle de AddOns pela tela de seleção de personagens.",
["How you doing?"]="Como vai você?",
["How's it hanging?"]="Como vão as coisas?",
["Hunters require focus to use their abilities.  Focus generates while standing still."]="Caçadores precisam de concentração para usar habilidades. A concentração é gerada ao ficar parado.",
["Hurry, fire!"]="Fogo! Depressa!",
["I am in your debt."]="Te devo uma.",
["I apologize profusely for any inconvenience my murderous rampage may have caused."]="Peço sinceras desculpas por qualquer inconveniente causado pela minha onda de assassinatos.",
["I be feeling you."]="Estamos de acordo.",
["I be in a bad way!"]="Estou mal!",
["I be in a bad way."]="Estou mal!",
["I be needing more mana!"]="Precisarei mais mana!",
["I believe so."]="Acredito que sim.",
["I can fulfill the role of:"]="Posso desempenhar a função de:",
["I can't find anywhere to get my nails done."]="Não encontro nenhum lugar para fazer as unhas.",
["I can't stand the smell of Orcs."]="Não suporto o cheiro dos orcs.",
["I can't wait till this quest is done, and I can look for another Garibaldi artifact."]="Mal posso esperar para terminar esta missão e procurar outro artefato Garibaldi.",
["I can't wait to suck the juice out of your eyeballs."]="Mal posso esperar para sugar seus globos oculares.",
["I come from the Orcs.  We eat with spoons and forks.  We love to eat our pork."]="Venho dos orcs. Comemos com colheres e garfos e adoramos carne de porco.",
["I dig it."]="Estou de acordo.",
["I do hope to find some interesting gadgets around here.  I do love tinkering with things."]="Espero encontrar alguns dispositivos interessantes por aqui. Adoro mexer em engenhocas.",
["I do not find you completely disagreeable."]="Você não me parece totalmente desagradável.",
["I don't care that much about romance.  I fell in love before, and look what happened to me."]="Não ligo muito para romance. Já me apaixonei uma vez, e veja no que deu.",
["I don't drink anymore.  'Course, I don't drink any less, either."]="Eu parei de beber... entre um gole e outro.",
["I don't feel that the 1 to 10 scale is fine enough to capture subtle details of compatibility.  I'd prefer a 12 dimensional compatibility scale with additional parameters for mechanical aptitude and torque."]="Não acho que uma escala de 1 a 10 seja precisa o bastante para avaliar os detalhes da compatibilidade. Eu preferiria uma escala de 12 dimensões, com parâmetros adicionais de aptidão mecânica e torque.",
["I don't have a drinking problem.  I drink, I get drunk, I fall down, no problem."]="Não tenho problema com bebida. Eu bebo, fico bêbado, caio e pronto.",
["I don't know about you, but I can't understand a thing those Wisps say.  I usually just nod."]="Não sei você, mas não entendo uma palavra do que os fogos-fátuos dizem. Normalmente só concordo com a cabeça.",
["I don't like to be underground.  It reminds me of death."]="Não gosto de ficar no subsolo. Isso me lembra a morte.",
["I don't mind the Gnomes, but I'm always worried about tripping over one."]="Não tenho nada contra os gnomos, mas sempre tenho medo de tropeçar em um deles.",
["I don't need to get funky.  I'm already there."]="Não há ninguém melhor que eu… quando se trata de jogar com a morte.",
["I don't smell that bad for a dead dude, do I?"]="Para ser um morto não cheiro tão mal, não?",
["I don't think so."]="Acho que não.",
["I feel pretty, oh so pretty (spit)."]="Eu me sinto bonita, tão bonita... (cospe).",
["I feel very feminine, and I'll beat the crap out of anyone who disagrees."]="Eu me sinto muito feminina e vou acabar com quem discordar.",
["I give myself a Dutch oven pedicure every night.  I've got no foot fungus at all.  My toes are pristine."]="Faço uma pedicure improvisada todas as noites. Não tenho nenhum fungo nos pés; meus dedos estão impecáveis.",
["I got a shrunken head.  I just came out of the pool."]="Minha cabeça encolheu. Acabei de sair da piscina.",
["I got all this and personality, too."]="Além do que vê, tenho uma grande personalidade.",
["I had an idea for a device that you could put small pieces of bread in to cook, but in the end I really didn't think there would be much of a market for it."]="Tive uma ideia de aparelho para torrar fatias de pão, mas achei que ninguém usaria algo assim.",
["I have a number of inventions I'd like to show you back at my place."]="Tenho algumas invenções em casa que gostaria de mostrar a você.",
["I have no respect for people with small piercings.  I say go full hog.  Put a spear through your head."]="Não respeito quem usa piercings pequenos. Se é para fazer, faça direito: atravesse a cabeça com uma lança.",
["I heard a knee slapper once, and skipped my kneecap right across a lake."]="A verdade é que sou tão graciosa que a vezes me parto eu sola.",
["I heard if you cut off an extremity, it'll regenerate a little bigger.  Don't believe it."]="Ouvi dizer que, se você cortar uma extremidade, ela cresce um pouco maior. Não acredite nisso.",
["I hope you're not afraid of snakes."]="Espero que você não tenha medo de cobras.",
["I hope you're well rested.  You're going to need your strength."]="Espero que tenha descansado bem. Você vai precisar de toda a sua força.",
["I kill two dwarves in the morning, I kill two dwarves at night.  I kill two dwarves in the afternoon, and then I feel alright. I kill two dwarves in time of peace and two in time of war. I kill two dwarves before I kill two dwarves, and then I kill two more."]="Mato dois anões pela manhã e pela noite outros dois. Mato dois anões pela tarde e já me sinto melhor. Mato dois anões em tempos de paz e outros dois em tempos de guerra. Mato dois anões antes de matar dois anões e justo depois outros dois.",
["I know.  My natural beauty is intimidating."]="Eu sei. Minha beleza natural intimida.",
["I lead the way."]="Eu vou na frente.",
["I like large posteriors, and I cannot prevaricate."]="Gosto de traseiros grandes e não posso mentir.",
["I like men who aren't afraid to cry; cry uncle."]="Gosto de homens que não têm medo de chorar. Vamos, peça arrego.",
["I like my ale like I like my men; dark and rich."]="Gosto da minha cerveja como gosto dos meus homens: escuros e encorpados.",
["I like my beer like I like my women; stout and bitter."]="Gosto da minha cerveja como gosto das minhas mulheres: encorpada e amarga.",
["I like my women dumpy and droopy with halitosis."]="Gosto de mulheres rechonchudas, caídas e com mau hálito.",
["I like tall men."]="Gosto de homens altos.",
["I like to fart in the tub."]="Gosto de soltar gases na banheira.",
["I look bigger in those mirrors where things look bigger."]="Pareço maior naqueles espelhos que aumentam tudo.",
["I love you like a fat kid loves cake."]="Gosto de você como uma criança gulosa gosta de bolo.",
["I must be asleep, cause you're a dream come true.  Also, I'm slightly damp."]="Devo estar sonhando, porque você é um sonho realizado. Além disso, estou um pouco úmido.",
["I need a hero."]="Preciso um herói.",
["I need healing!"]="Preciso de cura!",
["I need healing."]="Preciso de cura!",
["I need help!"]="Preciso de ajuda!",
["I need mana!"]="Preciso de mana!",
["I need more mana!"]="Preciso de mais mana!",
["I need some mana!"]="Preciso de mana!",
["I need to get my chest waxed again."]="Tenho que hacerme a cera no peito de novo.",
["I once laughed so hard, I milked all over the floor."]="Uma vez me reí tão forte que pringué todo somente de leche.",
["I owe you one."]="Te devo uma.",
["I require aid!"]="Preciso de ajuda!",
["I suppose so."]="Suponho que sim.",
["I thank you."]="obrigado",
["I think that guys just use the Emerald Dream as an excuse to avoid calling me back."]="Acho que esse pessoal usa o Sonho Esmeralda só como desculpa para não me ligar de volta.",
["I think that last vendor short changed me.  Oh, that was a bad one."]="Acho que ando curto de caminho. Vale, este é muito malo!",
["I want a man with soft hands.  Preferably four of them."]="Quero um macho com as mãos suaves. Se pode ser, com quatro mãos.",
["I will crush and destroy and... ooo... shiny..."]="Aplastaré e destruiré e… Ummm, que brilho.",
["I will lead the way."]="Eu conheço o caminho.",
["I will return the favor."]="Te retribuirei o favor.",
["I wish you well."]="Te desejo o melhor.",
["I won't bite you where it shows."]="Não você morderei onde se vê.",
["I won't fall for any bad pickup line.  You've got to try two or three, at least."]="Não vou cair por qualquer cantada ruim. Você terá que tentar pelo menos duas ou três.",
["I won't forget this."]="Não vou esquecer isso.",
["I would expect the same."]="Esperaríao mesmo.",
["I would like to join a group"]="Quero me juntar a um grupo",
["I'd like to give a shout out to my boys in Gnomeregan.  Keeping it real Big-T, Snoop-Pup, and Little Dees.  Y'all are short, but you're real, baby."]="Me gostaria saudar a meus colegas de Gnomeregan. Grande-T, Fisgón e Pequeno Dees... sois a leche. Pequenos, mas a leche.",
["I'd like to see you in a kilt."]="Me gostaria ver você com saia.",
["I'd paint my toenails, but I'm not sure where they fell off."]="Me pintaría as unhas, mas é que não as encontro.",
["I'll always treasure our time together."]="Aprecio muito o tempo que passamos juntos.",
["I'll give you crazy love."]="Te amarei como uma selvagem.",
["I'll have you know I can flatten steel with my thighs."]="Te informo de que sou capaz de achatar aço com os coxas.",
["I'll lead the way."]="Eu conheço o caminho.",
["I'll miss you."]="Te sentirei sua falta.",
["I'm a force of nature."]="Sou uma força da natureza.",
["I'm also looking for a group for:"]="Também estou procurando um grupo para:",
["I'm dead, and I'm pissed."]="Estou morto e estou furioso.",
["I'm in a rotten mood."]="Hoje cheiro a cachorro morto.",
["I'm looking for a group for:"]="Estou procurando um grupo para:",
["I'm out of mana!"]="Estou sem mana!",
["I'm short on mana!"]="Estou quase sem mana!",
["I'm the type of girl my mother warned me about."]="Sou o tipo de garota do que meu mãe sempre me quiso alejar.",
["I'm tired of the same old bull."]="Me cansei de sempre o mesmo.",
["I've discovered that getting pummeled by a blunt weapon can be quite painful."]="E descoberto que uma surra pode doer bastante.",
["I've got big soulful eyes, long eyelashes, and a wet tongue.  What more could a guy want?"]="Tenho os olhos grandes e enternecedores, largas estas e a grislíngua bem húmeda. Que mais pode desear um macho?",
["I've got no mana!"]="Estou sem mana!",
["IM Style"]="Estilo mensagem instantânea",
["INTERNAL ERROR, DISMOUNTING A NON-PET"]="ERRO INTERNO AO DESMONTAR DE UM item QUE NÃO É UM AJUDANTE",
["INTERNAL ERROR, YOU DON'T HAVE A PET TO DISMOUNT"]="ERRO INTERNO, VOCÊ NÃO TEM UM COMPANHEIRO DO QUAL DESMONTAR",
["Icon"]="Ícone",
["Icon Color"]="Cor do ícone",
["Icons in Chat"]="Ícones no Bate-papo",
["If I said you had a good body, would you hold it against me?"]="Se você dissesse que me gosta seu corpo, me daria um abraço?",
["If I wasn't purple, you'd see I was blushing."]="Se não fosse de cor roxo, veria que me e corado.",
["If cannibalism be wrong, I don't want to be right."]="Se o canibalismo está mal, não quero ser bom.",
["If checked, invitees whom respond to this event will have their status approved automatically; otherwise, you will have to approve them manually."]="Se esta opção estiver marcada, o status de quem informar a participação neste evento será aprovado automaticamente. Caso contrário, você precisará aprová-los manualmente.",
["If checked, invitees will be unable to respond to this event."]="Se esta opção estiver marcada, os convidados não poderão responder a este evento.",
["If enabled, you will be able to look at your map to see the locations of certain quest objectives."]="Se ativar esta opção, você poderá visualizar no mapa as localizações de alguns objetivos de missões.",
["If enabled, you will be able to review your talents in the Talent Interface before spending your talent points."]="Se está ativado, poderá revisar seus talentos na interface antes de gastar seus pontos de talento.",
["If enabled, you will only be able to receive loot by looting quest items, looting items that everyone passes on, or being given loot by the master looter."]="Se ativar esta opção, você receberá saque apenas se saquear itens de missões, itens recusados por todos ou se receber saques do mestre saqueador.",
["If enabled, your character will automatically dismount before casting while flying."]="Se essa opção for selecionada, o personagem desmontará automaticamente antes de lançar um feitiço durante o voo.",
["If enabled, your character will automatically switch between auto attack and auto shot."]="Se essa opção for selecionada, o personagem alternará automaticamente entre ataque automático e tiro automático.",
["If rot was hot, I'd be a volcano."]="Se o podre estivesse de moda, eu seria modelo.",
["If the Name Plate is displayed for your current target, show the enemy cast bar with the target's health bar in the game field."]="Se a Placa de Nome do alvo atual estiver sendo exibida, mostra a barra de lançamento do inimigo junto à barra de pontos de vida no campo de jogo.",
["If the sole purpose or intent of any action is to continually upset, aggravate, or otherwise annoy another player, that action may be considered physical harassment or �grief play�.  Before reporting physical harassment, make sure that the situation that is being petitioned falls outside the realm of the PvP policy (www.worldofwarcraft.com/policy/pvp.shtml). "]="Se a única intenção ou finalidade de uma ação for a de aborrecer, importunar ou irritar constantemente outro jogador, essa ação poderá ser considerada assédio físico ou �atitude desleal�. Antes de comunicar um caso de assédio físico, verifique se a situação denunciada está prevista ou não na política de JxJ. (www.worldofwarcraft.com/policy/pvp.shtml)",
["If there is another player you have enjoyed playing with, add them to your friends list! Click on the |cffffd200Social Button|r and add them to your list of friends.|n|nYou can only add friends from your own realm."]="Caso hajde outros jogadores com quem você tenha gostado de jogar, adicione-os à lista de amigos! Clique no |cffffd200Botão Social|r e adicione-os à lista de amigos.|n|nSó é possível adicionar amigos que façam parte do seu reino.",
["If this is checked, sound will be recorded in the movie."]="Se essa opção for marcada, o som será gravado no vídeo.",
["If this is checked, the game will offer the choice of compressing, ignoring, or deleting any pending movies when you log in."]="Se marcar esta opção, o jogo oferecerá a possibilidade de compactar, ignorar ou excluir quaisquer vídeos pendentes ao se conectar.",
["If this is checked, the movie will be compressed when you stop recording. Otherwise, you will need to use the compress button to finish processing the movies."]="Se ativar esta opção, o vídeo será compactado quando parar de gravar. Se não ativar, será necessário clicar no botão de compactação para terminar de processar os vídeos.",
["If this is checked, you will see a movie camera icon appear on the minimap frame while recording. If the user interface is recorded, this will also appear in the movie."]="Se essa opção for marcada, um ícone de câmera de vídeo será exibido na tela do minimapa durante a gravação. Se a interface do usuário for gravada, isso também aparecerá no vídeo.",
["If this is checked, you will see the cursor in the movie. Regardless of this setting, you will see the cursor while playing."]="Se essa opção for marcada, o cursor aparecerá durante o vídeo. Independentemente dessa configuração, o cursor aparecerá durante o jogo.",
["If this is checked, you will see the user interface in the movie. Regardless of this setting, you will see the user interface while playing."]="Se essa opção for marcada, a interface do usuário aparecerá no vídeo. Independentemente dessa opção, a interface do usuário aparecerá durante o jogo.",
["If you are the leader of a group, this button will add your current group to the battleground queue. Your group will be guaranteed to get into the same battleground instance at the same time.  Any group member added after you click this button or a group member in a queue for another battleground will not be guaranteed entrance to the same battleground."]="Se você for o líder de um grupo, este botão colocará seu grupo na fila para o Campo de Batalha. É garantido que todos os integrantes entrem na mesma instância de Campo de Batalha ao mesmo tempo. Qualquer integrante que se junte ao grupo depois de você ter clicado neste botão não terá a garantia de entrar no mesmo Campo de Batalha que você.",
["If you belong to a party, you can right-click your portrait to bring up the Party Options menu. This menu will allow you to quit the party or see what looting rules the party is using. A party leader can add or remove party members, as well as change the party's looting rules."]="Se pertencer a um grupo, você pode clicar com o botão direito no seu retrato para abrir o menu Opções de Grupo. Esse menu permite abandonar o grupo ou ver que regras de saque o grupo está usando. Líderes de grupos podem adicionar ou remover integrantes, além de alterar as regras de saque do grupo.",
["If you defeat an enemy and see sparkles on its corpse, that means it has loot.|n|n|cffffd200Right Click|r on a creature's corpse to loot it. This will open a loot window. Then |cffffd200Right Click|r on any items in that window to move them to your backpack."]="Se um inimigo derrotado exibir fagulhas no cadáver, isso indica que ele possui itens que podem ser saqueados.|n|n|cffffd200Clique com o Botão Direito do mouse|r no cadáver de uma criatura para saqueá-lo. Uma janela de saque aparecerá. A seguir, |cffffd200clique com o Botão Direito do mouse|r nos itens da janela para movê-los para a mochila.",
["If you find yourself stuck and unable to move, please try the auto-unstuck feature prior to petitioning a GM. In most cases, this should solve the problem. Activating the auto-unstuck command will first attempt to use your hearthstone to port you back to your inn. If this is not possible, it will attempt to nudge your character out of position.\n\nPlease note this option can only be used every 5 minutes. Using the auto-unstuck option will log your character and location so that we can verify and fix the location in the future."]="Se ficar preso e não conseguir se mover, tente primeiro o recurso de desbloqueio automático antes de pedir ajuda a um MJ. Na maioria dos casos, isso resolve o problema. Ao ativar o comando, o jogo tentará primeiro usar sua Pedra de Regresso para levar você de volta à estalagem. Se isso não for possível, tentará deslocar seu personagem para fora da posição em que ficou preso.\n\nEsta opção só pode ser usada uma vez a cada 5 minutos. O uso do desbloqueio automático registra seu personagem e a localização para que o problema possa ser verificado e corrigido no futuro.",
["If you replace this item, the following stat changes will occur:"]="Se substituir esse item, haverá as alterações de atributos abaixo:",
["If you stray into deep and uncharted waters, you will see a Fatigue bar. If you become completely fatigued, you will begin to drown."]="Se perambular por águas profundas e desconhecidas, aparecerá uma barra de Fadiga. Se ficar totalmente fatigado, você começará a se afogar.",
