["Ignored"]="Ignorado",
["Immediately report all language that is racist, extremely sexual, and/or violent; this type of language is always considered harassment."]="Denuncie imediatamente qualquer tipo de linguagem racista, extremamente sexual e/ou violenta. Esse tipo de linguagem sempre é considerado assédio.",
