["In my native tongue, my name means Dances with Tassels."]="Em meu idioma, meu nome indica dançando com bolas.",
["In the upper left corner of your screen is your health bar in green. When your health bar reaches zero, you will die, so be careful.|n|nBelow your health bar is a second bar representing the resource your class uses to power your special abilities, such as rage, energy or mana. Both bars will refill slowly over time."]="No canto superior esquerdo da tela fica sua barra de vida, em verde. Quando ela chega a zero, você morre — então não vacila.|n|nLogo abaixo fica a barra do recurso usado pela sua classe, como raiva, energia ou mana. As duas barras se recuperam aos poucos com o tempo.",
