["Increase multisampling to smooth out model edges. Increasing multisampling can severely reduce performance."]="Aumente a multiamostragem para suavizar as extremidades dos modelos. Aumentar a multiamostragem pode reduzir bastante o desempenho.",
["Increases Health and Mana regeneration rates. Spirit affects all\ncharacters' Mana and Hit Point regeneration rates in and\nout of combat."]="Aumenta as taxas de regeneração de Mana e de Vida. O espírito afeta as\ntaxas de regeneração de Mana e Pontos de Vida de todos os personagens em e\nfora de combate.",
["Increases Mana points as well as chance to Critical Hit\nwith magic spells. Intellect also grants a higher chance\nto increase melee skills. (It does not affect professions\nthough.)  "]="Aumenta os pontos de mana assim como a\nchance de acerto crítico com feitiços. Intelecto também\naumenta a chance de aprimorar perícias corpo a\ncorpo. (Não influencia profissões.)",
["Increases all characters’ chance to Critical Hit. The|namount of the bonus is higher per point on Rogues than|nother classes. Agility affects dodge. Rogues get more|nDodge per point of Agility than other classes. Agility|nadds directly to Armor."]="Aumenta a chance de acerto crítico de todos os personagens. O |nvalor do bônus por ponto é maior para Ladinos do que|noutras classes. Agilidade influencia na esquiva.|nLadinos ganham mais Esquiva por ponto de Agilidade do que|noutras classes. Agilidade afeta diretamente a Armadura.",
["Increases attack power with both melee and ranged weapons, and improves chance to score a critical hit with all weapons.|nIncreases armor and chance to dodge attacks."]="Aumenta o poder de ataque de armas corpo a corpo e de longo alcance e a chance de acerto crítico com todas as armas.|nAumenta a armadura e a chance de se esquivar de ataques.",
["Increases attack power with both melee and ranged weapons, and improves the chance to score a critical hit with all weapons.|nIncreases armor and chance to dodge attacks."]="Aumenta o poder de ataque de armas corpo a corpo e de longo alcance e a chance de acerto crítico com todas as armas.|nAumenta a armadura e a chance de se esquivar de ataques.",
["Increases attack power with melee weapons.\nIncreases the amount of damage that can be blocked with a shield."]="Aumenta o poder de ataque de armas corpo a corpo.\nAumenta o dano total que pode ser bloqueado com um escudo.",
["Increases attack power with ranged weapons.|nImproves chance to score a critical hit with all weapons.|nIncreases armor and chance to dodge attacks."]="Aumenta o poder de ataque de armas de longo alcance.|nAumenta a chance de acerto crítico com todas as armas.|nAumenta a armadura e a chance de se esquivar de ataques.",
["Increases health and mana regeneration rates."]="Aumenta as taxas de regeneração de mana e de vida.",
["Increases health points"]="Aumenta os pontos de vida",
["Increases health points."]="Aumenta os pontos de vida.",
["Increases mana points and chance to score a critical hit with spells.\nIncreases the rate at which weapon skills improve."]="Aumenta os pontos de mana e a chance de acerto crítico com feitiços.\nAumenta a taxa de melhoria de perícia com armas.",
["Increases texture sharpness, particularly for textures viewed at an angle.  Decrease to improve performance."]="Aumenta a nitidez da textura, especialmente texturas vistas em ângulo. Reduza para melhorar o desempenho.",
["Increases the rate at which weapon skills improve."]="Aumenta a taxa de melhoria de perícias com armas.",
["Increases the size of the Focus Frame to that of the Target Frame."]="Aumenta o tamanho da janela de foco para o mesmo da janela de alvo.",
["Increases the width of the Objectives tracker."]="Aumenta a largura do rastreador de Objetivos.",
["Increases weapon damage"]="Aumenta o dano com armas",
["Indicates how smoothly the game animates. Low framerate can be improved by changing your video options."]="Indica a fluidez da animação do jogo. Se a taxa de quadros por segundo estiver baixa, é possível aumentá-la alterando as opções de vídeo.",
["Indicates that you are willing to heal your allies when they take damage."]="Indica que você pretende assumir a função de curar os aliados quando receberem dano.",
["Indicates that you are willing to lead a group."]="Indica que você está disposto a liderar um grupo.",
["Indicates that you are willing to protect allies from harm by ensuring that enemies are attacking you instead of them."]="Indica que você pretende assumir a função de atrair os ataques dos inimigos para proteger os aliados.",
["Indicates that you are willing to take on the role of dealing damage to enemies."]="Indica que você pretende assumir a função de causar dano aos inimigos.",
["Indicates that you have some dungeon experience and are comfortable instructing the group in how to overcome the encounters."]="Indica que tem certa experiência com a masmorra e está disposto a ensenhar ao grupo como superar os vencer.",
