["Is that thing sharp?  Could that thing cut me?  I'm not immortal now, you know."]="Isso está afiado? Poderá cortarme? Agora não sou imortal, sabe?",
["Is there anything else you would like to tell us about? What could we have done to make this a better experience for you?"]="Gostaria de nos dizer algo mais? O que poderíamos ter feito para oferecer uma experiência melhor?",
["Issue:"]="Problema:",
["Issues regarding abilities, professions, reputation, and talents"]="Problemas relativos a habilidades, profissões, reputação e talentos",
["Issues regarding any problem dealing with item functionality or possession"]="Questões relativas a problemas com o funcionamento ou posse de itens",
["Issues that deal with NPCs and Creeps functioning or interacting incorrectly"]="Problemas relativos ao funcionamento e à interatividade incorretos de PNJs e Criaturas",
["Issues that deal with a character not being able to interact with the environment or operate in the environment"]="Problemas de interação ou movimentação do personagem no ambiente",
["It been real."]="Até pronto.",
["It is meant to be."]="Deve ser assim.",
["It is not meant to be."]="Não deveria ser assim.",
["It takes a long time after you try and use a spell or ability before the spell or ability actually occurs. Abilities may behave as if they are on cooldown even though they are not."]="Demora muito tempo desde o uso de um feitiço ou habilidade até que a ação de fato ocorra. As habilidades podem se comportar como se estivessem em recarga mesmo que não estejam.",
["It takes a long time for loot that you click on or that someone assigns to you to show up in your inventory. It may also take a long time to trade items with another player."]="Demora muito tempo para aparecer no inventário o saque em que clicou ou que lhe foi atribuído. A negociação de itens com outros jogadores também pode ser demorada.",
["It takes a long time for your friends to see messages you send them or for you to see messages they send you."]="Demora muito para seus amigos verem as mensagens que envia para eles ou para que veja as mensagens que enviam para você.",
["It takes a long time to open mail or retrieve items from mail."]="Demora muito para abrir mensagens ou recuperar itens de mensagens.",
["It was nothing."]="De nada.",
["It's always somebody else."]="Sempre o há alguém melhor que eu.",
["It's been fun."]="Fez divertido.",
["It's been quite an experience."]="Fez toda uma experiência.",
