["Raid: "]="Raide: ",
["Raids are groups of more than 5 people and are typically used to defeat unique challenges at high levels.\n\n|cffffffff- Raid members cannot earn credit toward most non-raid quests. Specifically, they will not receive non-raid quest credit for killing creatures or collecting items.\n\n- Raids grant substantially less experience for defeating monsters than normal groups.\n\n- Raids allow you to overcome challenges that might otherwise be nearly impossible.|r"]="Raides são grupos de mais de 5 pessoas e geralmente são usados para enfrentar desafios em níveis altos.\n\n|cffffffff- Os membros de um raide não ganham crédito pela maioria das missões que não são de raide. Mais especificamente, eles não recebem crédito em missões que não sejam de raide por matar criaturas ou coletar itens.\n\n- Raides concedem consideravelmente menos experiência pela morte de monstros do que grupos normais.\n\n- Raides permitem superar desafios que, de outro modo, seriam quase intransponíveis.|r",
