["Show messages when a spell cannot be cast or fails to cast."]="Exibir mensagens quando um feitiço não puder ser lançado ou se o lançamento falhar.",
["Show messages when a spell or ability creates an object."]="Exibir mensagens quando um feitiço ou habilidade criar um objeto.",
["Show messages when a spell or ability deals damage in reaction to a melee swing, such as Thorns."]="Exibir mensagens quando um feitiço ou habilidade causar dano em reação a um ataque corpo a corpo, como Espinhos.",
["Show messages when a spell or ability deals damage to a destructible building."]="Exibir mensagens quando um feitiço ou habilidade causar dano em um prédio destrutível.",
["Show messages when a spell or ability deals damage."]="Exibir mensagens quando um feitiço ou habilidade causar dano.",
["Show messages when a spell or ability fails to deal damage. This includes dodges, parries, blocks, deflections, immunes, absorbs and evades."]="Exibir mensagens quando um feitiço ou habilidade não causar dano. Inclui danos imunes, esquivas, aparos, bloqueios, absorções e desvios.",
["Show messages when a spell or ability fails to periodically deal damage. This includes immunes, absorbs and evades."]="Exibir mensagens quando um feitiço ou habilidade não causar dano periodicamente. Inclui danos imunes, absorvidos e desviados.",
["Show messages when a spell or ability grants additional attacks, such as Windfury Weapon or Sword Specialization."]="Exibe mensagens quando um feitiço ou habilidade concede ataques adicionais, como Arma de Fúria dos Ventos ou Especialização em Espadas.",
["Show messages when a spell or ability heals damage."]="Exibe mensagens quando um feitiço ou habilidade curar dano.",
["Show messages when a spell or ability interrupts another spell."]="Exibir mensagens quando um feitiço ou habilidade interromper outro feitiço.",
["Show messages when a spell or ability periodically deals damage, such as Shadow Word: Pain or Corruption."]="Exibir mensagens quando um feitiço ou habilidade, como Palavra Sombria: Dor ou Corrupção, causar dano periodicamente.",
["Show messages when a spell or ability periodically heals damage, such as Renew or Rejuvenation."]="Exibir mensagens quando um feitiço ou habilidade, como Renovar ou Rejuvenescer, curar periodicamente.",
["Show messages when a spell or ability periodically performs any other effect, such as restoring or draining mana."]="Exibe mensagens quando um feitiço ou habilidade produz outros efeitos periódicos, como restaurar ou drenar mana.",
["Show messages when a spell or ability reduces mana, energy, rage, focus or happiness."]="Exibe mensagens quando um feitiço ou habilidade reduz mana, energia, raiva, foco ou felicidade.",
["Show messages when a spell or ability repairs a building."]="Exibir mensagens quando um feitiço ou habilidade consertar um prédio.",
["Show messages when a spell or ability restores mana, energy, rage, focus, or happiness."]="Exibe mensagens quando um feitiço ou habilidade restaura mana, energia, raiva, foco ou felicidade.",
["Show messages when a spell or ability resurrects another player or creature."]="Exibir mensagens quando um feitiço ou habilidade ressuscitar outro jogador ou criatura.",
["Show messages when a spell or ability summons a creature or creates an object."]="Exibir mensagens quando um feitiço ou habilidade evocar uma criatura ou criar um objeto.",
["Show messages when a spell successfully completes."]="Exibir mensagens ao terminar de lançar um feitiço com sucesso.",
["Show messages when someone takes damage from falling, drowning or swimming in lava."]="Exibir mensagens quando alguém sofrer dano por queda, afogamento ou por nadar na lava.",
["Show messages when something dies."]="Exibir mensagens quando algo morrer.",
["Show on Backpack"]="Mostrar na mochila",
["Show only buffs you can cast on friendly targets.  Only applies to raids."]="Mostrar apenas benefícios que você pode lançar em alvos aliados. Aplica-se somente a raides.",
["Show only debuffs you can dispel on friendly targets.  Only applies to raids."]="Mostrar apenas penalidades que você pode dissipar de alvos aliados. Aplica-se somente a raides.",
["Show only the debuffs you applied on enemy targets."]="Exibir somente as penalidades usadas em alvos inimigos.",
["Show pet spell damage"]="Mostrar dano mágico do mascote",
["Show player titles in the game world."]="Exibe títulos de jogadores no mundo do jogo.",
["Show players' guild names in the game world."]="Exibe nomes das guildas dos jogadores no mundo do jogo.",
["Show ranged shots that deal full or partial damage."]="Exibe disparos a distância que causam dano total ou parcial.",
["Show ranged shots that fail to deal damage."]="Exibir disparos de longo alcance que não causaram dano.",
["Show spell damage caused by your pet."]="Mostra o dano do feitiço lançado pelo mascote.",
["Show spells that perform an effect incrementally."]="Exibir feitiços que causam efeito com incremento.",
["Show the portraits of the pets belonging to the enemy arena team."]="Exibir os retratos dos ajudantes que pertencem à equipe de arena adversária.",
["Show the portraits of your party members' pets."]="Exibir retratos dos ajudantes dos integrantes do grupo.",
["Show the range of raid members when they are far away by fading out their health bars."]="O esmaecimento das barras de vida indica que os integrantes do raide estão distantes.",
["Show the spell that your current target is casting."]="Exibe o nome do feitiço que o seu alvo está lançando.",
["Show the spells that players on the enemy arena team are casting."]="Exibir os nomes dos feitiços que os jogadores da equipe de arena adversária estão lançando.",
["Show track names in a pop up window automatically when tracks change in iTunes."]="Mostrar os nomes das faixas em uma janela pop-up automaticamente quando o iTunes mudar de faixa.",
["Show track names in a pop up window when you change tracks using the iTunes remote."]="Mostrar os nomes das faixas em uma janela pop-up quando você mudar de faixa no iTunes.",
["Show when a weapon enchantment is gained or removed."]="Exibir quando se obtém ou remove um encantamento de arma.",
["Show when an aura is removed, broken, or stolen."]="Mostrar quando uma aura for removida, quebrada ou roubada.",
["Show when you gain or lose a beneficial aura."]="Mostrar quando ganhar ou perder aura benéfica.",
["Show when you gain or lose a harmful aura."]="Mostrar quando ganhar ou perder aura prejudicial.",
["Shows /say and /yell text in speech bubbles above characters' heads."]="Mostra o texto de /say e /yell em balões de fala sobre as cabeças dos personagens.",
["Shows a message when an aura fades from the player."]="Exibe uma mensagem quando uma aura se desvanece do jogador.",
["Shows a message when the player gains or loses an aura."]="Exibe uma mensagem quando um jogador ganha ou perde uma aura.",
["Shows a message when the player gains or loses reputation with a faction."]="Exibe uma mensagem quando um jogador ganha ou perde reputação com uma facção.",
["Shows a message when you enter or leave combat. "]="Exibe uma mensagem quando você entra ou sai do combate.",
["Shows a screen edge flash when you have a fullscreen UI up and you are in combat."]="Exibe um clarão na borda da tela quando você estiver em combate utilizando a IU em tela cheia.",
["Shows all instant gains of mana, rage, and energy."]="Mostra todas as ganâncias instantâneos de mana, raiva e energia.",
["Shows all periodic gains of mana, rage, and energy."]="Exibe todos os ganhos periódicos de mana, raiva e energia.",
["Shows attacks against you that dodge, parry, or miss."]="Mostra os ataques sofridos que você esquivou, aparou ou que não o atingiram.",
["Shows attacks from bows, guns, thrown weapons, and wands."]="Exibe ataques de arcos, armas de fogo, armas arremessadas e varinhas.",
["Shows error messages related to UI functionality."]="Mostra mensagens de erro relativas à funcionalidade da Interface do Usuário.",
["Shows melee swings that deal full or partial damage."]="Exibe os ataques corpo a corpo que causam dano total ou parcial.",
["Shows message about beneficial and harmful state effects."]="Exibe mensagens sobre efeitos de estados benéficos e prejudiciais.",
["Shows messages about spells and special abilities."]="Mostra mensagens sobre feitiços e habilidades especiais.",
["Shows natural melee swings."]="Exibe ataques corpo a corpo naturais.",
["Shows party chat text in speech bubbles above party members' heads."]="Mostra o texto do bate-papo em grupo nos balões de fala acima das cabeças dos integrantes.",
["Shows the honor you gain from killing other players."]="Mostra a honra obtida ao matar outros jogadores.",
["Shows the name of a friendly caster when they cast a heal spell on you."]="Exibe o nome de um lançador aliado quando um feitiço de cura for lançado em você.",
["Shows the number of combo points you have each time you acquire a new one."]="Mostra o número de pontos de combo sempre que você ganha mais um.",
["Shows when reactive class specific abilities and spells become available (e.g. Overpower for warriors)."]="Mostra quando habilidades e feitiços reativos da sua classe ficam disponíveis, como Subjugar para guerreiros.",
