["So long."]="Até depois!",
["So, I have this idea for a great movie.  It's about two Gnomes who find a bracelet of power, and they have to take it to the Burning Steppes and cast it into The Cauldron.  They form the Brotherhood of the Bracelet.  Along the way, they're trailed by a murloc named Gottom who's obsessed with the bracelet, and nine bracelet bogeymen.  It could be a three parter called \"Ruler of the Bracelet\".  The first part would be called \"The Brotherhood of the Bracelet\", followed by \"A Couple of Towers\", with the climactic ending called \"Hey, the King's Back\"."]="Tive uma ideia genial para um filme: dois gnomos encontram uma pulseira do poder e precisam levá-la até as Estepes Ardentes para jogar no Caldeirão. Eles formam a Irmandade da Pulseira, mas são perseguidos por um murloc chamado Gottom, completamente fissurado na joia, e por nove assombrações de pulseira. Dá uma trilogia perfeita: \"O Senhor da Pulseira\". Primeiro vem \"A Irmandade da Pulseira\", depois \"Duas Torres, Mais ou Menos\" e o final épico: \"Olha Quem Voltou: o Rei\".",
["So, an Orc walks into a bar with a parrot on his shoulder.  The bartender says, \"Hey, where'd you get that?\"  The parrot says, \"Durotar.  They got 'em all over the place.\""]="Um orc entrar em um bar com um loro sobre o ombros. O barman lhe diz: \"Ouça, de onde tem sacado essa coisa?\". E o loro lhe responde: \"De Durotar. Ali há muitos\".",
["So, you want to fight for the glory of victory in the games? Well, you're going to have to wait. The Steamwheedle Cartel is taking a break after the great excitement of last season! Come back next week for your shot at glory! Feel free to practice in the meantime, but the true fun will have to wait."]="Então quer lutar pela glória nos jogos? Vai ter que esperar. O Cartel Bonvapor está descansando depois da emoção da última temporada! Volte na semana que vem para tentar conquistar a glória. Pode praticar até lá, mas a diversão de verdade terá que esperar.",
