["The amount of experience (XP) you have earned. The color of the XP bar indicates your rest state: light blue for Rested, and purple for Normal. Rested players earn twice the experience they would normally gain from slaying a monster. Characters become less rested when they kill monsters, and more rested by spending time at or logging out at an inn or city."]="A quantidade de experiência (EXP) adquirida. A cor da barra de EXP indica o estado de descanso: azul claro para Descansado e roxo para Normal. Jogadores descansados recebem o dobro de experiência por monstros mortos. Os personagens vão se cansando conforme matam monstros e descansam passando tempo ou se desconectando em estalagens ou cidades.",
["The amount of happiness your pet currently has. Content pets inflict normal damage on their enemies, whereas Happy pets inflict enhanced damage, and unhappy pets inflict reduced damage. Happiness goes down when your pet dies or as it grows hungry, while feeding your pet will increase its happiness."]="Nível de felicidade atual do seu mascote. Mascotes satisfeitos causam dano normal nos inimigos, mas mascotes felizes causam dano maior e mascotes infelizes causam danos reduzidos. A felicidade diminui quando o mascote morre ou fica faminto. Alimentar o mascote aumenta a felicidade dele.",
["The amount of health you currently have. If your health reaches zero, you will die. Health automatically regenerates when you are out of combat."]="O total de pontos de vida que você tem no momento. Se os pontos de vida chegarem a zero, você morrerá. Os pontos de vida se regeneram automaticamente quando você não está em combate.",
["The amount of mana you currently have. Players require mana in order to cast spells. Mana automatically regenerates if you have not cast a spell in the past five seconds."]="O total de mana que você tem no momento. Os jogadores precisam de mana para lançar feitiços. A mana se regenera automaticamente se você ficar cinco segundos sem lançar um feitiço.",
["The array of talents available to enhance and specialize your character."]="Os talentos disponíveis para melhorar e especializar o personagem.",
["The auction house is closed at the moment.|nPlease try again later."]="A casa de leilões está fechada.|nTente novamente mais tarde.",
["The battle for Wintergrasp is about to begin! Would you like to join the queue?"]="A batalha por Invérnia vai a começar! Que entrar à cola?",
["The chat entry box will work as it previously did. There will be a single entry box always attached to the primary Chat Frame."]="A caixa de digitação funcionará como anteriormente. Haverá apenas uma caixa de digitação sempre fixa à Janela de Bate-papo principal.",
["The door is locked."]="A porta está trancada.",
["The dungeon you chose does not support players from multiple realms."]="A masmorra selecionada não suportjogadores de reinos diferentes.",
["The durability of one of your items is getting low. The character icon below your minimap indicates the damaged item in yellow.|n|nFind a vendor in town to repair the item before it breaks."]="A durabilidade de um de seus itens está ficando baixa. O ícone do personagem abaixo do minimapa indica o item danificado em amarelo.|n|nEncontre um comerciante na cidade para consertar o item antes que se quebre.",
["The first random dungeon that you complete each day will earn you:"]="A primeira masmorra aleatória que completas cada dia você dará:",
["The following are NOT considered Non-quest NPC/Creep issues:"]="Esta é uma lista de exemplos que não são considerados problemas de Criaturas/PNJs que não são de missões:",
["The following are NOT considered Quest/Quest NPC issues:"]="Esta é uma lista de exemplos que NÃO são considerados problemas de Missão/PNJ de Missão:",
["The following are NOT considered item issues:"]="Esta é uma lista de exemplos que NÃO são considerados problemas com itens:",
["The following are NOT considered physical harassment:"]="Veja abaixo uma lista de exemplos que não são considerados assédios físicos:",
["The following are examples of Non-Quest NPC/Creep issues:"]="Estes são exemplos de problemas com Criaturas/PNJs que não são de missões:",
["The following are examples of Quest/Quest NPC issues:"]="Estes são exemplos de problemas com PNJs dentro e fora de missões:",
["The following are examples of Technical issues:"]="Estes são exemplos de problemas técnicos:",
["The following are examples of character issues:"]="Veja abaixo exemplos de problemas com o personagem:",
["The following are examples of environmental issues:"]="Estes são exemplos de problemas de ambiente:",
["The following are examples of guild issues:"]="Estes são exemplos de problemas de guildas:",
["The following are examples of item issues:"]="Estes são exemplos de problemas com itens:",
["The following are not considered environment issues:"]="Os casos a seguir não são considerados problemas de ambiente:",
["The following are the types of issues that a GM can assist with:"]="Estes são os tipos de problemas que um MJ pode ajudar a resolver:",
["The following spell will be cast on you:"]="O seguinte feitiço será lançado em você:",
["The further to the right your standing bar is the closer you are to improving your reputation to the next tier with that faction. The Standing Levels in order are Hated, Hostile, Unfriendly, Neutral, Friendly, Honored, Revered and Exalted."]="O progresso da barra de prestígio indica a reputação com a facção indicada. Quando a barra se enche, a reputação passa para o próximo nível. Em ordem crescente, os Níveis de Prestígio são Odiado, Hostil, Ignorado, Tolerado, Respeitado, Honrado, Reverenciado e Exaltado.",
["The guild bank does not have enough money"]="O banco da guilda não tem dinheiro suficiente.",
["The honor was mine."]="O honra fez meu.",
["The instance is full."]="A instância está cheia.",
["The item was not found."]="Não foi possível encontrar o item.",
["The merchant doesn't want that item."]="O mercador não quer esse item.",
["The number of invites that can be sent is limited, please wait to send another invite."]="A quantidade de convites que pode enviar é limitada. Espere para enviar outro convite.",
