["The party leader has attempted to reset the instance you are in.  Please zone out to allow the instance to reset."]="O líder do grupo tentou reiniciar a instância em que você se encontra.  Saia para permitir que a instância seja reiniciada.",
["The potions have all been depleted by Professor Putricide."]="Todas as poções foram usadas pelo Professor Putricida.",
["The selected path doesn't exist!"]="O caminho selecionado não existe!",
["The speed that events can be created is limited, please wait to create another event."]="Há um limite de criação de eventos por período. Espere para criar outro evento.",
["The spell cannot be cast on beastmaster or invis god targets."]="O feitiço não pode ser lançado em alvos que sejam senhores das feras ou deuses invisíveis.",
["The spell is not available to you"]="O feitiço não está disponível para você.",
["The target can't be in combat"]="O alvo não pode estar em combate",
["The target must be bound to you."]="O alvo deve estar vinculado a você.",
["The time for this event has already passed."]="O prazo deste evento já expirou.",
["The time it takes to talk with the game server. Consistently high (red) latencies may indicate a problem with your Internet connection."]="Tempo para estabelecer conexão com o servidor. Latência sempre alta (vermelho) pode ser um indício de problema na sua conexão com a Internet.",
["The total amount of damage done."]="A quantidade total de dano causado.",
["The total amount of healing done."]="A quantidade total de cura.",
["The voice session you are attempting to join is full."]="Você está tentando entrar em uma sessão de voz que está cheia.",
["The way to a man's heart be through his stomach, but I go through the rib cage."]="Dizem que o caminho para o coração de um homem passa pelo estômago, mas eu prefiro atravessar a caixa torácica.",
["The weather isn't right for that"]="O tempo não está bom para isso",
["There are no gems in this"]="Não há gemas nisto",
["There are no nearby corpses to eat"]="Não há cadáveres por perto que possam ser comidos",
["There are no nearby corpses to use"]="Não há cadáveres por perto que possam ser usados",
["There are no nearby party members on this quest."]="Não há integrantes do grupo próximos cumprindo esta missão.",
["There are no raids available at your level."]="Não há raides disponíveis no seu nível.",
["There are no valid targets within range."]="Não há alvos válidos dentro do alcance.",
["There are not enough players in the group to initate a vote."]="Não há jogadores suficientes no grupo para iniciar uma votação.",
["There are too many Mutated Abominations."]="Há Abominações Mutantes demais.",
["There aren't any fish here"]="Não tem peixe aqui",
["There be danger!"]="O perigo se aproxima!",
["There is a long delay when posting, buying, searching or paging through auctions."]="Há um longo atraso ao publicar, comprar, procurar ou passar as páginas dos leilões.",
["There is already a higher bid on that item."]="Esse item já tem um lance mais alto.",
["There is no direct path to that destination!"]="Não há caminho direto para esse destino!",
["There is no movie to compress."]="Não há vídeo para compactar.",
["There is no taxi vendor nearby!"]="Não há transporte próximo!",
["There is nobody to eject!"]="Não há quem ejetar!",
["There is nothing to attack."]="Não há o que atacar.",
["There were multiple players in the party with that name, please include realm name"]="Há vários jogadores no grupo com esse nome, inclua o nome do reino",
["There were no articles matching your search criteria."]="Nenhum artigo corresponde aos critérios de busca.",
["There's nothing like sleeping in the forest under the moonlight."]="Não há nada como dormir no florestas, baixo a luz da lua.",
["These Settings"]="Estas Definições",
["These are general gameplay related controls that affect how your character interacts with objects and other players in the game world."]="Estes são controles gerais do jogo que afetam como o personagem interage com objetos e outros jogadores no mundo do jogo.",
["These are the factions that you have interacted with."]="Estas são as facções com as quais você interagiu.",
["These are the lowest recommended graphics settings for the game. These settings provide excellent performance."]="Estas são as configurações mais baixas recomendadas para o jogo. Elas oferecem um desempenho excelente.",
["These are your active talents"]="Talentos ativos",
["These controls allow you to modify specific detail levels for many game elements and effects."]="Esses controles permitem modificar níveis de detalhes específicos para vários elementos e efeitos do jogo.",
["These items can't be swapped."]="Não é possível trocar estes itens.",
["These options affect whether certain UI and character elements are hidden or displayed."]="Estas opções determinam se certos elementos da interface de usuário e do personagem ficam ocultos ou são exibidos.",
["These options affect your character's behaviors in combat, and allow you to change the way combat is displayed in the UI."]="Estas opções afetam os comportamentos do personagem em combate e permitem alterar o modo de exibição de combate na IU.",
["These options allow you to change details having to do with stereoscopic (3D) viewing."]="Estas opções permitem alterar os detalhes relacionados à visualização estereoscópica (3D).",
["These options allow you to change the behavior of the help systems within the game."]="Estas opções alteram o funcionamento dos sistemas de ajuda no jogo.",
["These options allow you to change the size and detail in which your video hardware renders the game."]="Estas opções permitem alterar a resolução e os detalhes do jogo renderizados pelo hardware de vídeo.",
["These options allow you to change the types of Battle.net messages you receive."]="Estas opções alteram os tipos de mensagens do Battle.net que você receberá.",
["These options allow you to change the way the mouse behaves inside the game."]="Estas opções alteram o funcionamento do mouse no jogo.",
["These options allow you to configure the floating combat text which can be displayed in the center of the screen, making it easier to follow battles."]="Estas opções permitem configurar o texto de combate flutuante, que pode ser exibido no centro da tela, para facilitar o acompanhamento das batalhas.",
["These options allow you to control and modify your interactions with other players you encounter in Azeroth."]="Essas opções permitem controlar e modificar a interação com outros jogadores que você encontra em Azeroth.",
["These options allow you to control how buffs and debuffs are displayed."]="Estas opções controlam como os bônus e as penalidades são exibidos.",
["These options allow you to control which names are visible within the game field while you play."]="Estas opções controlam quais nomes são visíveis no campo de jogo enquanto você joga.",
["These options allow you to customize how game objectives like Quests and Achievements are displayed in the user interface,"]="Estas opções permitem personalizar a forma como os objetivos do jogo, como Missões e Conquistas, são exibidos na interface de usuário.",
["These options allow you to customize the behaviors of the game's quest interface."]="Estas opções personalizam o funcionamento da interface das missões do jogo.",
["These options allow you to display detailed information on status bars throughout the game."]="Estas opções permitem exibir informações detalhadas nas barras de status durante o jogo.",
["These options allow you to enable and disable full game features."]="Estas opções permitem ativar e desativar recursos especiais do jogo.",
["These options allow you to modify language settings for the game."]="Estas opções modificam as configurações de idioma do jogo.",
["These options allow you to modify the camera's behavior inside the game."]="Estas opções modificam o funcionamento da câmera no jogo.",
["These options can be used to change the display and behavior of party and raid frames within the UI."]="Estas opções alteram a exibição e o comportamento dos quadros de grupo e raide na interface de usuário.",
["These options can be used to change the display and behavior of unit frames within the UI."]="Estas opções são usadas para alterar a exibição e o funcionamento dos quadros de unidade na IU.",
["These options control sound hardware and input settings for the voice chat system."]="Estas opções controlam o hardware de som e as configurações de entrada para o sistema de bate-papo de voz.",
["These options control sound hardware and the types and volumes of sounds within the game."]="Estas opções controlam o hardware de som e os tipos e volumes de som dentro do jogo.",
["These options control the ranges and levels of detail used to draw effects and objects in the game."]="Estas opções controlam o alcance e os níveis de detalhes usados para formar efeitos e objetos no jogo.",
["These settings provide the very best quality and should only be used on high-end systems."]="Estas configurações oferecem a melhor qualidade possível e só devem ser usadas em sistemas avançados.",
["They will speak of your exploits for generations."]="Hablarán de seus proezas durante generações.",
["This Dungeon is In Progress."]="Esta Masmorra está em Andamento.",
["This Item Begins a Quest"]="Este item inicia uma missão",
["This Season"]="Série atual",
["This Week"]="Semana",
["This achievement has already been completed."]="Você já obteve esta conquista.",
["This allows you to save sets of equipment. You will then be able to equip a set by clicking on the icon. Once enabled, the Equipment Manager can be accessed through the character frame."]="Esta opção permite salvar conjuntos de equipamentos. Você poderá, então, equipar um conjunto ao clicar no ícone. Depois de ativado, o Gerenciador de Equipamentos pode ser acessado pela janela do personagem.",
["This codec is faster to compress than H.264 but it will generate a bigger file. "]="Este codec compacta mais rápido que o H.264, mas o arquivo gerado é maior.",
["This codec is supported natively by Apple devices like the iPod, iPhone and AppleTV. This codec has the best ratio quality/size but it is also the slowest to compress."]="Este codec é suportado de forma nativa por dispositivos da Apple, como iPod, iPhone e AppleTV. Este codec tem a melhor proporção de qualidade/tamanho, porém é mais lento ao compactar.",
["This determines how you will interact with members of this faction. If you have at war checked then your default behavior will be to attack them. If you do not have it checked you will not be able to attack them. "]="Determina como você irá interagir com membros desta facção. Se a opção \"em guerra\" estiver selecionada, seu comportamento padrão será atacá-los. Se ela não estiver selecionada, você não poderá atacar membros desta facção.",
["This doesn't mean I like you."]="Isto não quer dizer que me gustes.",
["This event has already occured."]="Este evento já aconteceu.",
["This event is locked."]="Este evento está bloqueado.",
["This guild bank tab is full"]="Esta aba do banco da guilda está cheia",
["This includes information about:  an upcoming patch (what, when, how), upcoming content additions, game play changes, and future rule changes."]="Isso inclui informações sobre futuros patches (o quê, quando e como), futuras expansões de conteúdo, mudanças na jogabilidade e futuras alterações nas regras.",
["This includes information about:  quests, non-player characters (NPCs), items, locations, or anything else that the player could possibly find out through exploration and/or interaction with the world or other players."]="Isto inclui informações acerca de: missões, personagens não jogadores (PNJS), itens, lugares ou qualquer outra coisa que o jogador poderá averiguar explorando ou interactuando com o mundo u outros jogadores.",
["This is a character you have enjoyed playing with on your realm, You can party and chat with this character."]="Você gostou de jogar com este personagem no seu reino. Você pode fazer um grupo e conversar com este personagem.",
["This is a flight master who trains flying beasts to carry passengers from one location to another. For a minimal fee, you can swiftly travel to other flight masters that you have spoken to in the past.|n|nWhen you discover a new city, finding the flight master will allow you to return easily in the future."]="Este é um mestre de voo que treina feras voadoras para carregarem passageiros de um lugar para outro. Por um preço módico, é possível viajar até outros mestres de voo com os quais você já tenha falado.|n|nQuando descobrir uma nova cidade, procure o mestre de voo para poder voltar facilmente depois.",
["This is a person you know and trust in real life. You will be able to chat with them no matter which Blizzard game you are playing. They must accept your friend invite, at which point your real name will be displayed to all of their friends."]="Esta é uma pessoa da vida real que você conhece e confia. Você poderá conversar com ela em qualquer jogo da Blizzard que estiver jogando. A outra pessoa precisa aceitar a sua confirmação de amizade. O seu nome verdadeiro será mostrado para todos os amigos dela.",
["This is a trial version of World of Warcraft. Some features are not available. To experience all of the game go to www.worldofwarcraft.com."]="Esta é uma versão de prova de World of Warcraft. Algumas opções não estão disponíveis. Para disfrutar do jogo entero, visite www.wow-europe.com.",
["This is how long you can record a movie before you run out of disk space. The game will stop recording after that time."]="Tempo de gravação de vídeo antes que acabe o espaço em disco. A gravação será interrompida depois desse tempo.",
["This is how much data needs to be written to your hard drive every second. If the game becomes very choppy while recording then it might be that the data rate is too high for your hard drive. The game will stop recording if it cannot write the data fast enough."]="Este é o volume de dados que precisa ser gravado no disco rígido por segundo. Se o jogo estiver emperrando muito durante a gravação, talvez a taxa de dados seja alta demais para o disco rígido. O jogo interrompe a gravação quando não consegue gravar os dados na velocidade necessária.",
["This is true love.  Do you think this happens every day?"]="Isto é amor verdadeiro. Te acha que essas coisas pasan todos os dias?",
["This is your announcement"]="Este é o seu anúncio",
["This is your event"]="Este é o seu evento",
["This is your guild event"]="Este é o seu evento da guilda",
["This item cannot be equipped."]="Não é possível equipar-se com este item.",
["This item cannot stack."]="Não é possível empilhar este item.",
["This item may not be disenchanted."]="Não é possível desencantar esse item.",
["This menu allows you to select the Voice Chat channel you would like to listen and speak in.  Right click to see a list of available voice chat channels."]="Este menu permite selecionar o canal do Bate-papo de Voz em que deseja falar ou ouvir.  Clique com o botão direito do mouse para visualizar uma lista de canais de bate-papo disponíveis.",
["This movie file is not valid."]="Este arquivo de vídeo não é válido.",
["This quest has no objectives to track"]="Esta missão não tem objetivos a listar",
["This quest requires an expansion enabled account."]="Esta missão exige uma conta com expansão ativada.",
["This should be a person you know and trust in real life. You will be able to chat with them no matter which Blizzard game you are playing. If you accept their friend invite your real name will be displayed to all of their friends."]="Esta deve ser uma pessoa da vida real que você conhece e confia. Você poderá conversar com ela em qualquer jogo da Blizzard que estiver jogando. Se você aceitar a confirmação de amizade, o seu nome será exibido para todos os amigos da outra pessoa.",
["This spell may only be used on Helpless Wintergarde Villagers that have not been rescued."]="Este feitiço só pode ser usado nos Aldeões de Invergarde Indefesos que não foram resgatados.",
["This stinks."]="Isto apesta.",
["This system is currently disabled."]="Este sistema está desativado.",
["This teleport crystal cannot be used until the teleport crystal in Dalaran has been used at least once."]="Este cristal de teleporte não pode ser usado até que o cristal de teleporte em Dalaran tenha sido usado ao menos uma vez.",
["This the one to fight!"]="Há que darle forte!",
["This way."]="Por aqui.",
["This will finish the compression early. You will lose the part that is still not compressed. The part that is currently compressed will be saved on your hard drive."]="Esta opção fará com que a compactação seja encerrada antecipadamente. Você perderá a parte que não foi compactada. A parte já compactada será salva no disco rígido.",
["This will reset your chat windows to default settings.\nYou will lose any custom settings."]="Isso fará com que as janelas de bate-papo sejam redefinidas para as configurações padrão.\nAs configurações personalizadas serão perdidas.",
["This will search for uncompressed movies and ask you if you want to compress, delete or ignore them."]="Marcar esta opção fará uma busca por vídeos não compactados e perguntará se deseja compactá-los, exclui-los ou ignorá-los.",
["This will show the World PVP objectives when you are in PVP zones."]="Esta opção mostra os objetivos de JxJ do mundo quando você estiver em zonas de JxJ.",
["This will show the World PVP objectives when you are near PVP points of interest."]="Esta opção mostra os objetivos de JxJ do mundo quando você estiver perto de pontos de interesse de JxJ.",
["This will turn off the World PVP objectives."]="Isto desativa os objetivos de JxJ do Mundo.",
