["To battle!"]="À batalha!",
["To create a guild you must purchase this charter, get 9 unique player signatures, and return the charter to me.  Please enter the desired name for your guild."]="Para criar uma guilda, você deve comprar este contrato, conseguir a assinatura de 9 jogadores e trazê-lo de volta. Digite um nome para a guilda.",
["To create an arena team you must purchase this charter, get the same number of unique player signatures as the size of your team, and return the charter to me.  Please enter the desired name for your arena team."]="Para criar um grupo de arena, você precisa comprar este contrato, conseguir um número de assinaturas de jogadores diferentes igual ao de integrantes da equipe e devolver o contrato a mim.  Digite o nome que desejar para a equipe de arena.",
["To fight enemies, first use |cffffd200Left Click|r to target them. Then click on one of the abilities on the action bar across the bottom of your screen.|n|nYou should use ranged abilities while the target is still far away. Other abilities require you to be close to your target, particularly if your class specializes in melee weapons."]="Para lutar, primeiro use o |cffffd200botão esquerdo|r para selecionar o inimigo. Depois, clique em uma habilidade na barra de ações.|n|nUse habilidades à distância enquanto o alvo estiver distante. Outras exigem que você chegue perto, principalmente nas classes focadas em combate corpo a corpo.",
["To free up bag space or make some money you can sell some of the items you have collected.|n|nLocate a vendor and |cffffd200Right Click|r them. Then open your bags and |cffffd200Right Click|r on any items you want to sell."]="Venda alguns dos itens coletados para liberar espaço na bolsa ou ganhar dinheiro.|n|nEncontre um vendedor e |cffffd200Clique com o Botão direito do mouse|r nele. A seguir, abra as suas bolsas e |cffffd200Clique com o Botão direito do mouse|r nos itens que deseja vender.",
["To get started, you should begin a |cffffd200Quest|r.|n|nThere's a quest giver right in front of you. Tutorial tips will help you along the way.|n|nThank you for playing, and good luck in your adventures!"]="Para começar, aceite uma |cffffd200Missão|r.|n|nTem um recrutador logo à sua frente. As dicas de tutorial ajudam no decorrer do tempo.|n|nObrigado por jogar e boa sorte em suas aventuras!",
["To my side!"]="A mí!",
