["Use mouse clicks to move your character to destinations."]="Clique com o mouse em um lugar para mover o personagem até lá.",
["Use the \"ALT\" key to Loot when \"Auto Loot\" is checked, and to Auto Loot when it is not."]="Use a tecla \"ALT\" para Saquear quando \"Saque Automático\" estiver marcado e para Saquear Automaticamente quando não estiver.",
["Use the \"ALT\" key to cast friendly target spells on yourself even if an enemy is targeted, or there is no target."]="Use a tecla \"ALT\" para lançar feitiços de alvos aliados em você mesmo ao selecionar um inimigo ou quando não houver alvo.",
