["Use the \"SHIFT\" key to Loot when \"Auto Loot\" is checked, and to Auto Loot when it is not."]="Use a tecla \"SHIFT\" para Saquear quando \"Saque Automático\" estiver marcado e para Saquear Automaticamente quando não estiver.",
["Use the \"SHIFT\" key to cast friendly target spells on yourself even if an enemy is targeted, or there is no target."]="Use a tecla \"SHIFT\" para lançar feitiços de alvos aliados em você mesmo ao selecionar um inimigo, ou se não houver alvo.",
