["You are now eligible to join battle. Click \"Enter Battle\" in the dialog or right click the battleground icon on the minimap."]="Agora você pode entrar na batalha. Clique em \"Entrar na Batalha\" na caixa de diálogo ou clique com o botão direito do mouse no ícone do campo de batalha no minimapa.",
