["You have completed your first quest! To collect your reward, you need to turn in the quest to a specific quest giver. Usually this is the same questgiver who gave you the quest.|n|nYou can see nearby questgivers as |cffffd200?|r on your minimap in the upper right of your screen. |cffffd200Right Click|r on a quest giver to talk to him or her."]="Você concluiu sua primeira missão! Para receber a recompensa, entregue-a ao personagem indicado. Geralmente, é o mesmo personagem que ofereceu a missão.|n|nOs personagens próximos que recebem missões aparecem com um |cffffd200?|r no minimapa, no canto superior direito da tela. Use o |cffffd200botão direito|r em um deles para conversar.",
["You have died.  Release spirit to enter Spectator Mode."]="Você morreu. Liberte o espírito para entrar no Modo Espectador.",
["You have died. Release to the nearest graveyard?"]="Você morreu. Deseja aparecer no cemitério mais próximo?",
["You have disbanded the guild."]="Você dissolveu a guilda.",
["You have entered too many instances recently."]="Você entrou em instâncias demais recentemente.",
["You have exited the battle for Wintergrasp."]="Tem saindo da batalha por Invérnia.",
["You have gained access to the totem bar! You will gain an action button on this bar whenever you gain access to a new totem element.|n|nThis bar can hold one totem spell per totem element. At higher level you will gain the ability to drop multiple totems at once."]="Você obteve acesso à barra de totens! A barra de ações receberá um botão de ação cada vez que você obtiver um novo elemento de totem.|n|nA barra pode conter um feitiço de totem por elemento de totem. Será possível usar vários totens ao mesmo tempo em níveis mais altos.",
["You have joined"]="Você entrou",
["You have joined a raid group."]="Você entrou em um grupo de raide.",
["You have joined a raid group: a group with an increased limit of 40 members, though usually 10 or 25. Raid groups are necessary to enter the most challenging dungeons or to defeat the most powerful enemies, typically at high level.|n|n|cffff2020While in a raid group, you will not earn credit towards most quests. To leave a raid group, Right Click on your character portrait and select Leave party.|r"]="Você entrou em um grupo de raide, com limite aumentado para 40 integrantes, mas os mais comuns são de 10 ou 25. É preciso participar de grupos de raide para entrar nas masmorras mais desafiadoras e derrotar os inimigos mais poderosos, geralmente em níveis altos.|n|n|cffff2020Você não receberá créditos para a maioria das missões enquanto estiver em um grupo de raide. Para sair de um grupo, clique com o botão direito do mouse no retrato do seu personagem e selecione Sair do grupo.|r",
["You have joined the guild."]="Você entrou na guilda.",
["You have learned a new spell or ability! Use the |cffffd200Spellbook & Abilities Button|r near the bottom of your screen to open your Spellbook. |cffffd200Left Click and drag|r a spell or ability to move it to your Action Bar.|n|nThe Spellbook is organized by category, as indicated by the tabs sticking out from the right side of the book."]="Você aprendeu um novo feitiço ou habilidade! Use o |cffffd200Botão do Grimório e Habilidades|r na parte inferior da tela para abrir o Grimório. |cffffd200Clique com o botão esquerdo e arraste|r um feitiço ou habilidade para movê-lo para a Barra de Ações.|n|nO Grimório é organizado por categorias, indicadas pelas abas na lateral direita do livro.",
["You have learned everything from that book"]="Você já aprendeu tudo desse livro",
["You have left the guild."]="Você saiu da guilda.",
["You have left the raid group."]="Você saiu do grupo de raide.",
["You have no friend requests"]="Não há solicitações de amizade",
["You have no recently updated stats"]="Não há estatísticas atualizadas recentemente",
["You have no target or your target is too far away."]="Você não tem alvo ou o alvo está longe demais.",
["You have no target."]="Não há alvo.",
["You have nobody to reply to yet."]="Ainda não há ninguém a quem responder.",
["You have not completed the required quest."]="Você ainda não cumpriu a missão necessária.",
["You have not earned any achievements recently"]="Você não obteve nenhuma conquista recentemente",
["You have not earned enough levels to grant any more levels"]="Você não ganhou níveis suficientes para conceder mais níveis",
["You have not spent any talent points."]="Não tem gasto nenhum ponto de talento.",
["You have obtained a ranged weapon. To use it, first equip the weapon by opening your |cffffd200Character Info|r and your |cffffd200Backpack|r and dragging the item onto your character.|n|nThen, open up your |cffffd200Spellbook|r and drag the |cffffd200Shoot|r or |cffffd200Throw|r ability onto your action bar.|n|nOnly hunters, warriors and rogues may use ranged weapons. Mages, priests and warlocks may use wands."]="Você obteve uma arma de longo alcance. Para usá-la, primeiro abra as |cffffd200Informações do Personagem|r e a |cffffd200Mochila|r e arraste o item para o personagem.|n|nA seguir, abra o |cffffd200Grimório|r e arraste a habilidade |cffffd200Atirar|r ou |cffffd200Arremessar|r para a barra de ações.|n|nSomente caçadores, guerreiros e ladinos podem usar armas de longo alcance. Magos, sacerdotes e bruxos podem usar varinhas.",
["You have pending calendar invites."]="Há convites de calendário pendentes.",
["You have reached the in-game cap of unique mail recipients"]="Você atingiu o limite máximo de mensagens para destinatários individuais",
["You have received a new friend request."]="Você tem uma nova solicitação de amizade.",
["You have received a ticket response. Click here to read it."]="A sua consulta foi respondida. Clique aqui para ler a resposta.",
["You have requested a duel."]="Você solicitou um duelo.",
["You have six different smiles; one for when you're angry, one for when you tear flesh, one for when you chew flesh, one for when you loot bodies, one for when you skin game, and one for when you want to kill something."]="Ela tem seis sorrisos diferentes. Um para quando está irritada, outro para quando rasga carne, outro para quando mastiga carne, outro para quando saqueia cadáveres, outro para quando esfola animais e o último para quando vai matar alguém.",
["You have the maximum number of those gems in your inventory or socketed into items."]="Você tem o máximo dessas gemas no seu inventário ou engastadas em itens.",
["You have the maximum number of those gems socketed into equipped items."]="Você tem o número máximo dessas gemas engastadas em itens equipados.",
["You have to be standing to attack anything!"]="Você precisa ficar de pé para atacar!",
["You have to be unsheathed to do that!"]="Você precisa desembainhar a arma para fazer isto!",
["You have too many of a unique item."]="Você tem unidades demais de um item.",
["You have too many of that item already"]="Você já tem itens demais deste tipo",
["You have too many pets already"]="Você já tem muitos ajudantes",
["You have unread mail"]="Você tem mensagens não lidas",
["You haven't reached that taxi node on foot yet!"]="Você primeiro precisa chegar a esse ponto de táxi a pé!",
["You haven't selected a champion"]="Você não selecionou um campeão",
["You know I have to keep moving at night or I'll disappear."]="Você sabe que preciso continuar me movendo à noite ou desapareço.",
["You know how hard it is to get your groove on with the spirit of your great grandmother looking over you?"]="Sabe como é difícil entrar no clima com o espírito da sua tataravó observando você?",
["You know those Ancient Protectors in Darnassas?  They're not that old."]="Sabe aqueles Protetores Anciãos de Darnassus? Eles não são tão antigos assim.",
["You know, I really wish I had a garden where I could put a couple of human statues."]="Sabe, eu adoraria ter um jardim onde pudesse colocar algumas estátuas de humanos.",
["You know, Taurens are born hunters.  You ever see a Tauren catch a salmon out of a stream?  It really is quite exciting.  And, have you ever seen a Tauren stalk a python?  'Course you haven't.  That's because Taurens are so adept at blending in with their surroundings."]="Você sabe, os tauren nascem caçadores. Já viu um tauren pegar um salmão no rio? É emocionante. E já viu um tauren espreitar uma serpente? Claro que não. Isso acontece porque os tauren são especialistas em se camuflar no ambiente.",
["You know, Wisps are actually pretty useful for personal hygiene."]="Sabia que fogos-fátuos são bem úteis para a higiene pessoal?",
["You know, older bulls really only have one function."]="Sabe, touros mais velhos só têm uma função.",
["You know, once you're dead, nothing smells bad anymore.  Rotten eggs?  No problem.  Dead fish?  Like a spring breeze."]="Sabe? Quando está morto, já nada cheira mal. Ovos podres? Não há problema. Peixe morto? Como uma brisa de primavera.",
["You know, squirrels can be deadly when cornered."]="Você sabe que uma ardilha encurralada pode ser mortal.",
["You leave the group."]="Você sai do grupo.",
["You look pretty.  I like your hair.  Here's your drink.  Are you ready now?"]="Está guapa. Me gosta seu cabelo. Aí tem seu bebida. Já está lista?",
["You look pretty.  Pretty tasty."]="Está para comerte. Com patatas.",
["You may find that a solution for your issue has already been posted on the Technical Support Forum, located on the World of Warcraft site at:\n\nwww.worldofwarcraft.com\n\nIf your technical issue is not addressed by the solutions posted there, please contact our Technical Support Department:\n\nBy Phone at:  (949) 955-1382\nBy Web at: http://us.blizzard.com/support/index.xml?gameId=11\nBy Email at:  wowtech@blizzard.com"]="Verifique primeiro se há uma solução para o seu problema no Fórum de Suporte Técnico, no site do World of Warcraft em\n\nwww.worldofwarcraft.com\n\nSe se problema técnico não for resolvido pelas soluções do fórum, entre em contato com o Departamento de Suporte Técnico:\n\nTelefone:  (949) 955-1382\nNa Web: http://us.blizzard.com/support/index.xml?gameId=11\nPor e-mail: wowtech@blizzard.com",
["You may not bite other vampires."]="Você não pode morder outros vampiros.",
["You may not create custom channels with profane names."]="Não é possível criar canais personalizados com nomes profanos.",
["You may not list yourself in the Raid Browser while you are queued for a Dungeon."]="Você não pode passar o mousete no Localizador de Raides enquanto está em fila para uma masmorra.",
["You may not queue for a Dungeon while you are listed in the Raid Browser."]="Você não pode em fila para uma masmorra enquanto estiver inscrito no Localizador de Raides.",
["You may not queue for this dungeon."]="Você não pode entrar na fila para esta masmorra.",
["You may not queue for this."]="Você não pode entrar na fila para isto.",
["You may not queue while one or more of your team members is under the effect of restricted play."]="Não é possível entrar na fila quando um ou mais integrantes da equipe estão com restrições de jogo.",
["You may not trade an item with a temporary enhancement."]="Não é possível negociar um item com encantamento temporário.",
["You may only call down a Wintergarde Gryphon in Wintergarde Keep or the Carrion Fields."]="Só é possível chamar um Grifo de Invergarde na Bastilha Invergarde ou nos Campos de Carniça.",
["You may only call down a stampede on Harold Lane."]="Só é possível chamar uma sanha em Manuelzão.",
["You may only call for the aid of a Wyrmrest Vanquisher in Wyrmrest Temple, The Dragon Wastes, Galakrond's Rest or The Wicked Coil."]="Só é possível pedir a ajuda de um Subjugador do Repouso das Serpes no Templo do Repouso das Serpes, no Ermo das Serpes, no Repouso de Galakrond ou na Espiral Perversa.",
["You may only trade bound items to players that were originally eligible to loot the item"]="Você só pode negociar itens vinculados com jogadores que podiam saquear o item",
["You may only trade conjured items to players from other realms"]="Só é possível negociar itens conjurados com jogadores de outros reinos",
["You may only use the Pouch of Crushed Bloodspore on Gammothra or other magnataur in the Bloodspore Plains and Gammoth."]="Só é possível usar a Bolsa de Sanguesporo Macerado em Gamutra ou outro magnatauro nas Planícies Sanguesporo e Gamute.",
["You may want to invite other players to team up with you to more easily overcome your enemies.|n|nMany difficult quests can be quickly completed in a group, as quest credit is shared by the group. Moreover, groups earn bonus experience, relative to solo players."]="Você pode convidar outros jogadores para a equipe a fim de derrotar seus inimigos.|n|nMuitas missões difíceis podem ser concluídas rapidamente por um grupo, que compartilha o crédito pela missão. Além disso, grupos ganham mais experiência, em comparação com jogadores individuais.",
["You move me."]="Me conmueves.",
["You must advance to a higher level."]="Você deve alcançar um nível mais alto.",
["You must be a guild master to purchase a tabard, but feel free to browse."]="Só o mestre da guilda pode comprar tabardos, mas pode olhar à vontade.",
["You must be behind your target."]="É necessário estar atrás do alvo.",
["You must be close to a marked tree."]="Você precisa estar perto de uma árvore marcada.",
["You must be closer to a plague wagon in order to drop off your 7th Legion Siege Engineer."]="É necessário estar mais perto de uma carroça pestilenta para soltar o Engenheiro de Cerco da 7ª Legião.",
["You must be closer to a sinkhole to use your map."]="Você precisa estar perto de uma fossa para usar o mapa.",
["You must be closer to the buoy!"]="Você precisa estar mais perto da boia!",
["You must be facing the corpse to loot it."]="Para saquear o cadáver, é preciso estar de frente para ele.",
["You must be flagged for PvP in order to help capture this objective."]="Você precisa estar sinalizado como JxJ para ajudar a capturar este objetivo.",
["You must be in a raid group to enter this instance."]="É necessário fazer parte de um grupo de raide para entrar nesta instância.",
["You must be in front of your target."]="É necessário estar na frente do alvo.",
["You must be in stealth mode."]="Você precisa estar em modo furtivo.",
["You must be joking."]="Só pode ser brincadeira.",
["You must be near the Maiden of Winter's Breath Lake."]="Você precisa estar perto da Donzela do Lago Sopro Invernal.",
["You must be sitting in a barber chair"]="É necessário estar sentado em uma cadeira de barbearia",
["You must be standing to do that"]="Você precisa estar de pé para fazer isso",
["You must be the party leader to interact with the meeting stone"]="Somente o líder do grupo pode interagir com a pedra de encontro",
["You must be unsheathed"]="Sua arma precisa estar desembainhada",
["You must be within range of a Helpless Wintergarde Villager."]="Você precisa estar ao alcance de um Aldeão de Invergarde Indefeso.",
["You must choose a category to submit your bug/suggestion."]="Escolha uma categoria para enviar o erro/sugestão.",
["You must choose a reward."]="Escolha uma recompensa.",
["You must either be in a party or currently be looking for a group to join Looking For More."]="Você precisar estar em um grupo ou procurando um grupo para escolher Procurando Mais.",
["You must enter text for your ticket."]="Digite o texto da consulta.",
["You must enter the instance to recover your corpse"]="Você precisa entrar na instância para recuperar seu cadáver",
["You must equip that item to use it."]="Você precisa equipar-se com esse item para usá-lo.",
["You must first select a Proto-Drake Egg."]="Você precisa selecionar primeiro um Ovo de Protodraco.",
["You must have The Burning Crusade expansion installed to access this area."]="Você precisa instalar a expansão The Burning Crusade para acessar esta área.",
["You must have The Wrath of the Lich King expansion installed to access this area."]="Você precisa instalar a expansão The Wrath of Lich King para acessar esta área.",
["You must have a Fire Totem active."]="Deve ter um totem de Fogo ativo.",
["You must have a demonic circle active."]="Você precisa escolher um círculo demoníaco ativo.",
["You must have a lance equipped."]="É necessário estar equipado com uma lança.",
["You must meet the min bid."]="Você precisa cobrir o lance mínimo.",
["You must obtain better gear."]="Deve obter melhor equipamento.",
["You must promote a new Guild Master using /gleader before leaving the guild."]="Você precisa promover um novo Mestre da Guilda usando /gleader antes de sair da guilda.",
["You must promote a new team captain using /teamcaptain before leaving the team."]="Você precisa promover um novo capitão usando /teamcaptain antes de sair da equipe.",
["You must purchase that bag slot first"]="É preciso primeiro comprar o compartimento para a bolsa",
["You must reach level 58 to use this portal."]="Você precisa chegar ao nível 58 para usar esse portal.",
["You must repair that item before you auction it."]="É necessário consertar esse item antes de leiloá-lo.",
["You must repair that item's durability to use it."]="Você precisa reparar a durabilidade desse item para usá-lo.",
["You must select at least one role."]="Você deve selecionar ao menos uma função.",
["You must specify a loot master."]="É necessário especificar um mestre saqueador.",
["You must specify a target: /<command> <target's name>"]="É necessário especificar um alvo: /<comando> <nome do alvo>",
["You must target a Fjord Hawk."]="Você precisa selecionar um Falcão do Fiorde.",
["You must target a Fjord Turkey."]="Você precisa selecionar um Peru do Fiorde.",
["You must target a weakened chill nymph."]="Você precisa selecionar uma ninfa gélida enfraquecida.",
["You must unequip that item first"]="Você precisa remover esse item primeiro",
["You need Evasive Charges"]="Você precisa de cargas evasivas",
["You need more signatures."]="Você precisa de mais assinaturas.",
["You need to be closer to interact with that target."]="Você precisa estar mais próximo para interagir com esse alvo.",
["You need to be in a party to use a meeting stone"]="Você precisa estar em um grupo para usar uma pedra de encontro",
["You need to be standing to go anywhere."]="É preciso estar de pé para se locomover.",
["You need to be standing up to loot something!"]="Para saquear cadáveres é preciso estar de pé!",
["You need to have at least a level 20 character on your account."]="É necessário ter ao menos um personagem de nível 20 na sua conta.",
["You now have a keyring to hold your keys.This |cffffd200Keyring Button|r appears to the left of your bags on your action bar."]="Agora você tem um chaveiro para guardar as chaves. O |cffffd200Ícone do Chaveiro|r fica à esquerda das bolsas na barra de ações.",
["You really want the item."]="Você realmente quer o item.",
["You received a bag. Now you will be able to carry more items.|n|nMove the bag to an empty bag space next to your backpack. Click on a bag to open it."]="Tem recebido uma bolsa. Agora poderá lhevar mais itens.|n|nColocà bolsa em um espaço de bolsa vazio junto a seu mochila. Clique acima para abrirla.",
["You recently deserted a Dungeon Finder group and may not queue again for:"]="Tem abandonado de um grupo de Localizador de Masmorras recentemente e você não pode voltar a entrar na fila até dentro de:",
["You recently queued for a Random Dungeon.\nYou may queue for another in:"]="Você entrou na fila recentemente para uma Masmorra Aleatória.\nVocê poderá entrar novamente na fila para outra em:",
["You scratch my back, I scratch yours."]="Você me rascas a costas e eu você a rasco a ti.",
["You shall be granted the title:"]="Você receberá o título:",
["You should be proud."]="Você deveria se orgulhar.",
["You stay here."]="Você você restas aqui.",
["You want to Greed the item, but you want it disenchanted if you win the roll."]="Você escolhe Ganância para o item, mas o quer desencantado se vencer a disputa.",
["You were Away for a ready check"]="Você estava Ausente em uma verificação de jogadores prontos",
["You were not referred by that player"]="Você não usou a indicação desse jogador",
["You will also receive the following rewards. They scale with the number of random players included in your group:"]="Você também receberá as seguintes recompensas. Elas aumentam de acordo com o número de jogadores aleatórios no grupo:",
["You will also receive:"]="Também receberá:",
["You will be able to choose one of these rewards:"]="Você poderá escolher uma dentre estas recompensas:",
["You will be unflagged for PvP combat after five minutes of non-PvP action in friendly territory."]="Você será desmarcado para combate JxJ após cinco minutos de atividade que não seja relacionada a JxJ em território aliado.",
["You will learn how to create:"]="Você aprenderá a criar:",
["You will learn:"]="Você aprenderá:",
["You will lose any unsaved changes if you switch between general and character specific key bindings."]="Você perderá as alterações que não forem salvas se alternar entre a configuração geral do teclado e a específica do personagem.",
["You will lose your initial deposit by canceling this auction."]="O seu depósito inicial não poderá ser recuperado se cancelar este leilão.",
["You will no longer be able to view your response message if you mark it as read. Are you sure you want to mark your message read?"]="Você não poderá mais visualizar a resposta se a marcar como lida. Tem certeza de que deseja marcar sua resposta como lida?",
["You will no longer be able to view your response message if you request more help. Are you sure you want to open a follow-up ticket?"]="Você não poderá mais visualizar a resposta se solicitar ajuda adicional. Tem certeza de que deseja abrir uma consulta de réplica?",
["You will receive:"]="Você receberá:",
["You will see a Breath bar pop up when your character becomes submerged in water. If you run out of breath, you will begin to drown."]="Aparecerá uma barra de Respiração quando o personagem ficar submerso na água. Se ficar sem ar, você começará a se afogar.",
["You'd like to run your hands through my beard, wouldn't you?"]="Você gostaria de passar as mãos na minha barba, não gostaria?",
["You'll do.  Let's go."]="Me conformaré com você. Vamos.",
["You'll take the item, but only if nobody else really wants it."]="Você ficará com o item, mas apenas se nenhum outro jogador realmente o quiser.",
["You're already mounted."]="Você já está em uma montaria.",
["You're an Emerald Dream come true."]="É um Sonho Esmeralda feito realidade.",
["You're not mounted!"]="Você não está em uma montaria!",
["You're the type I'd like to sink my teeth into."]="É de essas pessoas a as que me gostaria hincarles o diente.",
["You're too busy to follow anything!"]="Você está muito ocupado para seguir qualquer coisa!",
["You're too far away from Zafod's Transponster! The rocket pack won't fire."]="Você está muito longe do Transportador de Zafod! A mochila-foguete não dará a partida.",
["You're welcome."]="De nada.",
["You've already signed another guild charter"]="Você já assinou outro contrato de guilda",
["You've created enough ghouls. Return to Gothik the Harvester at Death's Breach."]="Você já criou carniçais suficientes. Fale novamente com Gothik, o Ceifador, que fica na Vanguarda da Morte.",
["You've got me all a flutter."]="Estou realmente entusiasmada.",
["You've reached your limit of bag slots!"]="Você atingiu o limite de compartimentos para bolsas!",
["Your"]="Seu",
["Your AddOns are experiencing a large number of errors and may be slowing down the game.  You can turn on display of Lua errors in the interface options."]="Há muitos erros relacionados aos seus AddOns e isso pode estar reduzindo o desempenho do jogo.  É possível ativar a exibição de erros de Lua nas opções de interface.",
["Your Current Issue:"]="Problema atual:",
["Your Enchanting skill is not high enough to disenchant that"]="Sua perícia de Encantamento não é alta o bastante para desencantar esse item.",
["Your IGR's playtime is about to expire, you will be disconnected shortly."]="O seu tempo de conexão está prestes a terminar. Você será desconectado em breve.",
["Your Iron Rune Construct is out of range."]="O Constructo da Runa Férrea está fora de alcance.",
["Your Random Dungeon group is ready!"]="O seu grupo para a Masmorra Aleatória está pronto!",
["Your Rating"]="Seu ranque",
["Your Role"]="Sua função",
["Your ability to form a complete sentence is a plus."]="Saber montar uma frase inteira já conta pontos a seu favor.",
["Your arena team has reached the limit of created events."]="A equipe de arena alcançou o limite de eventos criados.",
["Your attack rating affects your chance to hit a target, and is based on the weapon skill of the weapon you are currently wielding."]="A taxa de ataque afeta sua chance de acertar um alvo e baseia-se na perícia com a arma que você está empunhando.",
["Your attendant already has an Argent Pony"]="O seu criado já possui um Pônei Argênteo",
["Your bags are full so you won't be able to pick up any more loot. To free up some bag space, visit vendor characters and sell them some of your junk.|n|nThere are usually vendors in every city, town or outpost."]="As bolsas estão cheias e você não poderá saquear mais nada. Para liberar espaço na bolsa, fale com os vendedores e venda um pouco das suas coisas.|n|nGeralmente, há vendedores em todas as cidades e postos.",
["Your bank is full"]="O banco está cheio",
["Your bid increment is too small."]="O incremento do lance é muito pequeno.",
["Your bid:"]="Seu lance:",
